CREATE TABLE consent_definitions (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), purpose VARCHAR(40) NOT NULL, title VARCHAR(160) NOT NULL, content VARCHAR(4000) NOT NULL, revision INTEGER NOT NULL, active BOOLEAN NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE consent_records (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), child_id UUID NOT NULL REFERENCES children(id), definition_id UUID NOT NULL REFERENCES consent_definitions(id), status VARCHAR(40) NOT NULL, definition_revision INTEGER NOT NULL, content_snapshot VARCHAR(4000) NOT NULL, guardian_user_id UUID NOT NULL REFERENCES users(id), decided_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL, CONSTRAINT consent_records_unique_guardian_definition UNIQUE (child_id, definition_id, guardian_user_id));
